import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  // Load the mesh
  const gltf = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');
  const mesh = gltf.scene;

  // Add mesh to group (preserve mesh's internal transforms)
  group.add(mesh);

  // Apply scene placement to group
  group.position.set(-1.25, -1.1, 0);

  // Initialize handlers
  group.userData.handlers = {};

  // Store original position for hover revert
  const originalY = group.position.y;

  // Hover interaction: rise-in (0.15 scene units)
  group.userData.handlers.hover = (event) => {
    gsap.killTweensOf(group.position);
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: originalY - 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  // Unhover: return to original position
  group.userData.handlers.unhover = (event) => {
    gsap.killTweensOf(group.position);
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  // Click interaction: emit hub-features.select
  group.userData.handlers.click = (event) => {
    if (ctx.emit) {
      ctx.emit('hub-features.select');
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(primitive => {
      const primitiveFn = ctx.primitives[primitive.name];
      if (primitiveFn && typeof primitiveFn === 'function') {
        primitiveFn(group, primitive.params);
      }
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    // Kill all timelines
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // Dispose mesh resources
    mesh.traverse(child => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
